import{_ as a,o as n,a as p,b as c}from"./app.C41L12d5.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMT API","link":"/api/SIMT-API/SIMT-API"},{"text":"同步与内存栅栏","link":"/api/SIMT-API/sync_and_memory_fence/sync_and_memory_fence"},{"text":"同步与内存栅栏简介","link":"/api/SIMT-API/sync_and_memory_fence/sync_and_memory_fence_intro"}]},"headers":[],"relativePath":"api/SIMT-API/sync_and_memory_fence/sync_and_memory_fence_intro.md","filePath":"api/SIMT-API/sync_and_memory_fence/sync_and_memory_fence_intro.md","outlineHeaders":[{"level":2,"title":"API列表","slug":"API列表","link":"#API列表"},{"level":2,"title":"同步屏障","slug":"同步屏障","link":"#同步屏障"},{"level":2,"title":"内存栅栏","slug":"内存栅栏","link":"#内存栅栏"},{"level":2,"title":"使用建议","slug":"使用建议","link":"#使用建议"}],"lastUpdated":1787050286000}'),l={name:"api/SIMT-API/sync_and_memory_fence/sync_and_memory_fence_intro.md"};function e(t,s,d,o,r,h){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>同步与内存栅栏简介</h1><p>SIMT程序中，不同Thread的执行进度和内存访问到达顺序可能不同。当线程之间存在数据依赖时，需要使用同步接口或内存栅栏接口约束执行顺序和内存可见性。</p><p>同步机制主要分为两类：</p><ul><li><strong>同步屏障（barrier）</strong>：要求同一作用范围内的线程都到达指定位置后，程序才能继续执行。</li><li><strong>内存栅栏（memory fence）</strong>：约束调用线程在栅栏前后的内存访问顺序，使栅栏前的内存操作按指定范围对其他线程可见。内存栅栏不会等待其他线程到达同一位置。</li></ul><h2 id="API列表">API列表<a class="header-anchor" href="#API列表">​</a></h2><table><thead><tr><th>类型</th><th>接口名</th><th>作用范围</th><th>是否阻塞线程</th><th>功能说明</th></tr></thead><tbody><tr><td>同步屏障</td><td><a href="sync_interface/asc_syncthreads.html">asc_syncthreads</a></td><td>当前Thread Block</td><td>是</td><td>等待当前Thread Block内所有Thread都执行到该同步点，并保证同步点前的内存操作对块内线程可见。</td></tr><tr><td>内存栅栏</td><td><a href="memory_fence/asc_threadfence_block.html">asc_threadfence_block</a></td><td>当前Thread Block</td><td>否</td><td>保证调用线程在栅栏前的内存操作，按顺序对当前Thread Block内的其他线程可见。</td></tr><tr><td>内存栅栏</td><td><a href="memory_fence/asc_threadfence.html">asc_threadfence</a></td><td>全局范围</td><td>否</td><td>保证调用线程在栅栏前的全局内存和共享内存写操作，按顺序对其他线程可见。</td></tr></tbody></table><h2 id="同步屏障">同步屏障<a class="header-anchor" href="#同步屏障">​</a></h2><p><code>asc_syncthreads</code>用于Thread Block内的阶段同步。典型场景是多个Thread先写入Unified Buffer（UB）中的共享数据，再统一进入下一阶段读取这些数据。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="nf">__launch_bounds__</span><span class="p">(</span><span class="mi">256</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">block_reduce</span><span class="p">(</span><span class="kt">float</span><span class="w"> </span><span class="o">*</span><span class="n">out</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="o">*</span><span class="n">in</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">buf</span><span class="p">[</span><span class="mi">256</span><span class="p">];</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">tid</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>

<span class="w">    </span><span class="n">buf</span><span class="p">[</span><span class="n">tid</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">in</span><span class="p">[</span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">tid</span><span class="p">];</span>

<span class="w">    </span><span class="c1">// 等待当前Thread Block内所有Thread完成buf写入。</span>
<span class="w">    </span><span class="n">asc_syncthreads</span><span class="p">();</span>

<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">tid</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="kt">float</span><span class="w"> </span><span class="n">sum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mf">0.0f</span><span class="p">;</span>
<span class="w">        </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">            </span><span class="n">sum</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="n">buf</span><span class="p">[</span><span class="n">i</span><span class="p">];</span>
<span class="w">        </span><span class="p">}</span>
<span class="w">        </span><span class="n">out</span><span class="p">[</span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">sum</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>使用<code>asc_syncthreads</code>时需要注意：</p><ul><li>同一Thread Block内的所有Thread必须都执行到该同步点，否则已经到达同步点的Thread会一直等待，导致程序无法继续执行。</li><li>避免在分支中调用<code>asc_syncthreads</code>，除非可以保证当前Thread Block内所有Thread都会进入该分支。</li><li><code>asc_syncthreads</code>只同步当前Thread Block内的Thread，不能用于不同Thread Block之间的全局同步。</li></ul><h2 id="内存栅栏">内存栅栏<a class="header-anchor" href="#内存栅栏">​</a></h2><p>内存栅栏用于约束调用线程的内存访问顺序。它解决的是“某个线程先写数据、再发布状态或标志”这类可见性问题，但不会阻塞其他线程，也不会让其他线程自动等待。</p><p>典型的生产者-消费者场景如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">data</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">value</span><span class="p">;</span>

<span class="c1">// 确保data写入先于后续标志位更新对其他线程可见。</span>
<span class="n">asc_threadfence</span><span class="p">();</span>

<span class="n">asc_atomic_exch</span><span class="p">(</span><span class="n">ready</span><span class="p">,</span><span class="w"> </span><span class="mi">1U</span><span class="p">);</span>
</code></pre></div><p>在上述场景中，<code>asc_threadfence</code>保证调用线程在栅栏前的数据写入先于标志位更新对其他线程可见。消费者线程仍需要通过轮询、原子操作或其他同步方式判断<code>ready</code>状态，内存栅栏本身不会等待消费者线程。</p><p><code>asc_threadfence_block</code>与<code>asc_threadfence</code>的区别在于作用范围不同：</p><ul><li><code>asc_threadfence_block</code>用于Thread Block内的数据可见性顺序约束，适合块内共享数据和UB协作场景。</li><li><code>asc_threadfence</code>用于更大范围的数据可见性顺序约束，适合通过Global Memory发布数据或标志的场景。</li></ul><h2 id="使用建议">使用建议<a class="header-anchor" href="#使用建议">​</a></h2><ul><li>需要Thread Block内所有Thread完成某一阶段后再继续执行时，使用<code>asc_syncthreads</code>。</li><li>只需要保证当前Thread的内存写入顺序和可见性时，使用<code>asc_threadfence_block</code>或<code>asc_threadfence</code>。</li><li>不要将内存栅栏当作同步屏障使用。内存栅栏不会等待其他Thread，也不保证其他Thread已经执行到同一位置。</li><li>不要将<code>asc_syncthreads</code>当作跨Thread Block同步接口使用。不同Thread Block之间如需共享状态，应结合Global Memory、<a href="../atomic_operations/atomic_operations.html">原子操作</a>和内存栅栏设计同步协议。</li><li>多个Thread并发写同一地址时，<code>asc_syncthreads</code>和内存栅栏都不能替代原子操作；需要避免写冲突，或使用原子操作保证读改写过程的原子性。</li></ul></article></div>`,1)])])}const m=a(l,[["render",e]]);export{_ as __pageData,m as default};
